import clsx from 'clsx';
import React, { ChangeEvent, forwardRef } from 'react';

import { CheckmarkIcon, XmarkIcon } from '@dynatrace/strato-icons';

import {
  switchIconCSS,
  switchLabelCSS,
  switchTextCSS,
  switchThumbCSS,
  switchWrapperCSS,
} from './Switch.sty.js';
import { _VisuallyHidden as VisuallyHidden } from '../../core/components/visually-hidden/VisuallyHidden.js';
import { _useControllableState } from '../../core/hooks/useControllableState.js';
import { _useFormControlState } from '../../core/hooks/useFormControlState.js';
import { _useSharedInputPropsContext } from '../../core/hooks/useSharedInputPropsContext.js';
import { useFocusRing } from '../../core/styles/useFocusRing.js';
import type { AriaLabelingProps } from '../../core/types/a11y-props.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { DOMProps } from '../../core/types/dom.js';
import type { FormControlStateProps } from '../../core/types/form-control-state.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import type { WithChildren } from '../../core/types/with-children.js';
import { mergeProps as _mergeProps } from '../../core/utils/merge-props.js';
import { Flex } from '../../layouts-core/flex/Flex.js';
import { Hint } from '../forms-core/components/hint/Hint.js';
import { _useFormFieldContext } from '../forms-core/hooks/useFormFieldContext.js';
import { FormFieldAction } from '../forms-core/state/formfield-state-reducer.js';
import { _useInputHint } from '../hooks/useInputHint.js';

// #region Types
export type SwitchProps = SwitchBaseProps &
  (SwitchControlledProps | SwitchUncontrolledProps);

export interface SwitchBaseProps
  extends WithChildren,
    DOMProps,
    FormControlStateProps,
    AriaLabelingProps,
    StylingProps,
    DataTestId {
  /** The string used as the value of the switch when submitting it in a form, if the switch is toggled on. */
  formValue?: string;
  /**
   * Whether the switch is disabled or not.
   * If true, the switch cannot be clicked in order to toggle its state.
   * @defaultValue false
   */
  disabled?: boolean;
  /**
   * Whether the switch is required or not.
   * If true, the switch is marked with an asterisk.
   * @defaultValue false
   */
  required?: boolean;
}

export interface SwitchUncontrolledProps {
  /**
   * The default on or off state.
   * @defaultValue false
   */
  defaultValue?: boolean;
  /** The name used for the switch button, that identifies it when submitting it in a form. */
  name: string;
  /** Whether the switch is toggled on or off. */
  value?: never;
  /** Handler that is called when the 'on' attribute changes. */
  onChange?: never;
}

export interface SwitchControlledProps {
  /** Whether the switch is on or off. */
  value: boolean;
  /** Handler that is called when the 'on' attribute changes. */
  onChange: (checked: boolean, event?: ChangeEvent<HTMLInputElement>) => void;
  /** The name used for the switch, that identifies it when submitting it in a form. */
  name?: string;
  /** The default on or off state. */
  defaultValue?: never;
}
// #endregion

/**
 * The `Switch` component allows users to toggle between two different states. You can
 * set a specific initial value using the `defaultValue` prop for an uncontrolled switch
 * or setting the initial value of the state of a controlled switch accordingly. The `name` prop also
 * needs to be specified for identifying the `Switch` when submitting it in a form.
 */
export const Switch = /* @__PURE__ */ forwardRef<HTMLDivElement, SwitchProps>(
  (props: SwitchProps, forwardedRef) => {
    const {
      value,
      defaultValue = false,
      children,
      controlState,
      name,
      formValue,
      onChange,
      className: consumerClassName,
      style: consumerStyle,
      'data-testid': dataTestId,
      id: propId,
      required: propRequired,
      disabled: propDisabled,
    }: SwitchProps = props;

    const {
      controlId,
      required: contextRequired,
      disabled: contextDisabled,
      dispatch,
    } = _useFormFieldContext();

    if (
      (propId !== undefined && propId !== controlId) ||
      (propDisabled !== undefined && propDisabled !== contextDisabled) ||
      (propRequired !== undefined && propRequired !== contextRequired)
    ) {
      dispatch?.({
        type: FormFieldAction.UPDATE,
        payload: {
          id: propId,
          disabled: propDisabled,
          required: propRequired,
        },
      });
    }

    const disabled = propDisabled || contextDisabled;
    const required = propRequired || contextRequired;

    const { id, labelId } = _useSharedInputPropsContext({
      id: propId || controlId,
    });

    const [hasError, hint] = _useFormControlState(controlState);
    const { containerProps, inputProps, hintProps } = _useInputHint({
      hint,
      hasError,
    });

    if (value !== undefined && !onChange) {
      // eslint-disable-next-line no-console
      console.error(
        'Defining "value" makes the switch controlled. Set the onChange() callback and implement the toggle functionality.',
      );
    }

    const [isSelected, setIsSelected] = _useControllableState({
      value,
      defaultValue,
    });

    const color = isSelected ? 'primary' : 'neutral';
    const errorFocusColor = hasError ? 'critical' : color;

    const { focusClassName, focusProps, isFocusVisible } = useFocusRing({
      variant: disabled ? 'neutral' : errorFocusColor,
    });

    /** The callback function when the state changes */
    function handleChange(e?: ChangeEvent<HTMLInputElement>): void {
      if (!disabled) {
        onChange?.(!isSelected, e);
        setIsSelected(!isSelected);
      }
    }

    return (
      <Flex
        ref={forwardedRef}
        data-testid={dataTestId}
        flexDirection="column"
        gap={4}
        className={consumerClassName}
        style={consumerStyle}
        {...containerProps}
      >
        <label htmlFor={id} className={switchLabelCSS({ disabled })}>
          <VisuallyHidden>
            <input
              id={id}
              type="checkbox"
              role="switch"
              aria-disabled={disabled === true ? disabled : undefined}
              checked={isSelected}
              aria-checked={isSelected}
              aria-label={props['aria-label']}
              aria-labelledby={props['aria-labelledby'] || labelId}
              aria-describedby={props['aria-describedby']}
              aria-details={props['aria-details']}
              onChange={handleChange}
              name={name}
              value={formValue}
              {..._mergeProps(focusProps, inputProps)}
            />
          </VisuallyHidden>
          <div
            className={clsx(
              focusClassName,
              switchWrapperCSS({ disabled, color, hasError, isFocusVisible }),
            )}
            data-testid="switch-wrapper"
          >
            <div
              className={switchIconCSS({
                selected: isSelected,
                disabled,
                hasError,
              })}
            >
              <CheckmarkIcon size="small" />
              <div
                className={switchThumbCSS({
                  selected: isSelected,
                  disabled,
                  hasError,
                })}
              />
              <XmarkIcon size="small" />
            </div>
          </div>
          <span
            className={switchTextCSS({
              disabled,
              required: !!children && required,
            })}
          >
            {children}
          </span>
        </label>
        <Hint hasError={hasError} disabled={disabled} {...hintProps}>
          {hint}
        </Hint>
      </Flex>
    );
  },
);
(Switch as typeof Switch & { displayName: string }).displayName = 'Switch';
